// Generated by scripts/generate-html-entities.mjs from the WHATWG table.
// This subset preserves mdream's prior names and every legacy semicolonless
// reference without shipping the full HTML entity table in each JS bundle.
// A $ prefix marks canonical-only names; unprefixed names may omit semicolons.
export const HTML_ENTITIES: Readonly<Record<string, string>> = /* @__PURE__ */ (() => {
  const entities: Record<string, string> = {
    AMP: '&',
    $Dagger: '‡',
    GT: '>',
    LT: '<',
    $OElig: 'Œ',
    $Prime: '″',
    QUOT: '"',
    $Scaron: 'Š',
    $Yuml: 'Ÿ',
    $alefsym: 'ℵ',
    amp: '&',
    $and: '∧',
    $ang: '∠',
    $apos: '\'',
    $asymp: '≈',
    $bdquo: '„',
    $bull: '•',
    $cap: '∩',
    $circ: 'ˆ',
    $clubs: '♣',
    $cong: '≅',
    copy: '©',
    $crarr: '↵',
    $cup: '∪',
    $dArr: '⇓',
    $dagger: '†',
    $darr: '↓',
    $diams: '♦',
    $empty: '∅',
    $equiv: '≡',
    $euro: '€',
    $exist: '∃',
    $fnof: 'ƒ',
    $forall: '∀',
    $frasl: '⁄',
    $ge: '≥',
    gt: '>',
    $hArr: '⇔',
    $harr: '↔',
    $hearts: '♥',
    $hellip: '…',
    $image: 'ℑ',
    $infin: '∞',
    $int: '∫',
    $isin: '∈',
    $lArr: '⇐',
    $lang: '⟨',
    $larr: '←',
    $lceil: '⌈',
    $ldquo: '“',
    $le: '≤',
    $lfloor: '⌊',
    $lowast: '∗',
    $loz: '◊',
    $lsaquo: '‹',
    $lsquo: '‘',
    lt: '<',
    $mdash: '—',
    $minus: '−',
    $nabla: '∇',
    $ndash: '–',
    $ne: '≠',
    $ni: '∋',
    $notin: '∉',
    $nsub: '⊄',
    $oelig: 'œ',
    $oline: '‾',
    $oplus: '⊕',
    $or: '∨',
    $otimes: '⊗',
    $part: '∂',
    $permil: '‰',
    $perp: '⊥',
    $piv: 'ϖ',
    $prime: '′',
    $prod: '∏',
    $prop: '∝',
    quot: '"',
    $rArr: '⇒',
    $radic: '√',
    $rang: '⟩',
    $rarr: '→',
    $rceil: '⌉',
    $rdquo: '”',
    $real: 'ℜ',
    reg: '®',
    $rfloor: '⌋',
    $rsaquo: '›',
    $rsquo: '’',
    $sbquo: '‚',
    $scaron: 'š',
    $sdot: '⋅',
    $sigmaf: 'ς',
    $sim: '∼',
    $spades: '♠',
    $sub: '⊂',
    $sube: '⊆',
    $sum: '∑',
    $sup: '⊃',
    $supe: '⊇',
    $there4: '∴',
    $thetasym: 'ϑ',
    $tilde: '˜',
    $trade: '™',
    $uArr: '⇑',
    $uarr: '↑',
    $upsih: 'ϒ',
    $weierp: '℘',
  }

  const latin1Names = 'nbsp iexcl cent pound curren yen brvbar sect uml COPY ordf laquo not shy REG macr deg plusmn sup2 sup3 acute micro para middot cedil sup1 ordm raquo frac14 frac12 frac34 iquest Agrave Aacute Acirc Atilde Auml Aring AElig Ccedil Egrave Eacute Ecirc Euml Igrave Iacute Icirc Iuml ETH Ntilde Ograve Oacute Ocirc Otilde Ouml times Oslash Ugrave Uacute Ucirc Uuml Yacute THORN szlig agrave aacute acirc atilde auml aring aelig ccedil egrave eacute ecirc euml igrave iacute icirc iuml eth ntilde ograve oacute ocirc otilde ouml divide oslash ugrave uacute ucirc uuml yacute thorn yuml'.split(' ')
  for (const [index, name] of latin1Names.entries()) {
    if (name)
      entities[name] = String.fromCharCode(0xA0 + index)
  }

  // The empty slot matches the gap before Greek capital sigma. The final
  // sigma has its own name and is listed with the literals.
  const greekNames = 'alpha beta gamma delta epsilon zeta eta theta iota kappa lambda mu nu xi omicron pi rho  sigma tau upsilon phi chi psi omega'.split(' ')
  for (const [index, name] of greekNames.entries()) {
    if (!name)
      continue
    entities[`$${name}`] = String.fromCharCode(0x3B1 + index)
    entities[`$${name[0]!.toUpperCase()}${name.slice(1)}`] = String.fromCharCode(0x391 + index)
  }
  return entities
})()

export const MAX_ENTITY_NAME_LENGTH = 8
export const MAX_LEGACY_ENTITY_NAME_LENGTH = 6
